/**
 * street-furniture.js — the 1904 district's street furniture: the gas lamps on the
 * parkways (T-3199).
 *
 * WHAT IT DRAWS, from `data/street_furniture/<scene>.json` (generated by
 * tools/lay_prairie_1904_street_furniture.py from the T-0474 grid, the T-2474 section
 * and the T-2473 elms): a cast-iron gas lamp post at every intersection corner of the
 * district's drawn streets, the lamps the photographs show in front of their houses,
 * and the rest of each parkway at a reconstructed spacing. Each item names its kind,
 * its place, its grade and the pictures that show it; a pictured one is attested and
 * the rest are reconstructed (docs/LIBERTIES.md L-prairie-street-lamps-3199).
 *
 * HOW. Every lamp is the same post, so each part of it (the iron, the lantern's glass,
 * the stone footing at a corner) is one procedural geometry drawn INSTANCED, at two
 * levels by distance from the eye: the near set at full detail (foot, collar, leafed
 * boss, shaft, capital, ladder bar, bent arms, tapered lantern, waist band, glazed top
 * and cap; T-3219 and T-3231, read off the 1811 photograph) casting the sun's shadow, and the
 * far set as a plain post and lantern that casts none. A lamp whose class the file gives a
 * model of its own (`model_by_class`: T-1934's globe post, Pullman's on 18th Street) is drawn
 * the same way from that model's parts. Past the far ring a lamp is not
 * drawn. The phone's `light` tier pulls both rings in and casts nothing. The sets are
 * re-dealt only when the eye has moved a few metres, from a list of about a hundred.
 * No binary asset: the post is built here, to the measures the data file states.
 *
 * NO LIGHT. The scene is a July morning and has no night (world.js), so the lanterns
 * are glass in daylight and nothing is lit.
 *
 * A scene that does not list `street_furniture` hands this no data base and it draws
 * nothing; a failed fetch draws nothing and records a problem. A pick on a post opens
 * a card built from the file's own records: what it is, its grade, and its pictures.
 */

import * as THREE from 'three';

const PARKWAY_LIFT_M = 0.05;      // street-grid.js CLASSES.parkway.lift
const CONF = { attested: 0, inferred: 0.5, reconstructed: 1 };
/** Rings, metres from the eye: full detail inside `near`, the plain post to `far`. */
const RINGS = {
  full: { near: 70, far: 520, shadow: true },
  balanced: { near: 55, far: 420, shadow: true },
  light: { near: 30, far: 200, shadow: false },
};
const REDEAL_M = 3;
// A hydrant is under a metre tall: past this it is a speck, so it is not drawn at all.
const HYDRANT_FAR_M = { full: 160, balanced: 130, light: 90 };
const KINDS = ['gas_lamp', 'fire_hydrant', 'utility_pole'];
const POLE_CLASSES = ['street', 'alley', 'trolley'];

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/* -------------------------------------------------------------------------- */
/* the post                                                                    */
/* -------------------------------------------------------------------------- */

function merge(parts) {
  const geos = parts.map((g) => (g.index ? g.toNonIndexed() : g));
  let n = 0;
  for (const g of geos) n += g.attributes.position.count;
  const pos = new Float32Array(n * 3); const nor = new Float32Array(n * 3);
  let o = 0;
  for (const g of geos) {
    if (!g.attributes.normal) g.computeVertexNormals();
    pos.set(g.attributes.position.array, o * 3);
    nor.set(g.attributes.normal.array, o * 3);
    o += g.attributes.position.count;
  }
  for (const g of geos) g.dispose();
  for (const g of parts) g.dispose();
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  out.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  out.computeBoundingSphere();
  return out;
}

const at = (g, y, rotY = 0) => { if (rotY) g.rotateY(rotY); g.translate(0, y, 0); return g; };
const lathe = (profile, seg) => new THREE.LatheGeometry(profile.map(([r, y]) => new THREE.Vector2(r, y)), seg);
/** A square frustum whose faces look along the local axes (a four-segment cylinder is a
 *  square on its diagonal, so it is turned an eighth). `w` is the side, not the radius. */
const square = (wTop, wBottom, h, open = false) => at(
  new THREE.CylinderGeometry(wTop / Math.SQRT2, wBottom / Math.SQRT2, h, 4, 1, open), 0, Math.PI / 4);

/**
 * The lamp post, in the post's own frame: y up from the ground it stands on, local x
 * along the street. `m` is the data file's `model_m` (T-3219: read off the 1811
 * photograph, the clearest post of the district, against Taylor 2135 and 2140's
 * second view). From the ground: a plain round foot on a plinth, a moulded collar, the
 * leafed boss, a slender shaft, the capital under the ladder bar, a stem whose four
 * arms bend up into the lantern's foot, the lantern's glass tapering out to an iron
 * waist band, a steep glazed top on iron hips (T-3231: the 1811 print sees the trees
 * through it), and a small cap, vent and knob. Returns { iron, tin, glass } for the
 * near level and the far level, with the tinned cap as `tin`.
 */
function lampGeometry(m) {
  const H = m.height_m ?? 3.12;
  const foot = m.foot_m ?? { r: 0.115, plinth_r: 0.135, to: 0.59 };
  const collar = m.collar_m ?? { to: 0.7, r: 0.12 };
  const boss = m.boss_m ?? { to: 0.97, r: 0.12, leaves: 8 };
  const [rS0, rS1] = m.shaft_r_m ?? [0.065, 0.055];
  const cap = m.capital_m ?? { from: 2.03, to: 2.2, r: 0.085 };
  const bar = m.ladder_bar_m ?? { at: 2.23, w: 0.36 };
  const lan = m.lantern_m ?? { foot: 2.45, top: 2.77, w_foot: 0.17, w_top: 0.44 };
  const rim = m.rim_m ?? { w: 0.48, h: 0.035 };
  const roof = m.roof_m ?? { top: 3.03, w_top: 0.1 };
  const vent = m.vent_m ?? { w: 0.14, h: 0.05 };
  const stemTop = lan.foot - 0.1;
  // The turned iron from the ground to the capital's top: plinth, foot, collar mouldings,
  // the boss, the shaft and the capital's bell, one lathe.
  const turned = lathe([
    [0, 0], [foot.plinth_r, 0], [foot.plinth_r, 0.04], [foot.r + 0.01, 0.07], [foot.r, 0.09],
    [foot.r, foot.to - 0.03], [collar.r * 0.92, foot.to - 0.01], [collar.r, foot.to + 0.02],
    [collar.r, foot.to + 0.05], [collar.r * 0.8, foot.to + 0.07], [collar.r * 0.86, collar.to - 0.02],
    [collar.r * 0.75, collar.to],
    [boss.r * 0.8, collar.to + 0.02], [boss.r, collar.to + (boss.to - collar.to) * 0.35],
    [boss.r * 0.95, collar.to + (boss.to - collar.to) * 0.7], [boss.r * 0.62, boss.to - 0.02],
    [rS0 + 0.012, boss.to], [rS0 + 0.012, boss.to + 0.03], [rS0, boss.to + 0.05],
    [rS1, cap.from - 0.03], [rS1 + 0.012, cap.from - 0.01], [rS1 + 0.012, cap.from + 0.01],
    [cap.r * 0.8, cap.from + 0.05], [cap.r, cap.from + (cap.to - cap.from) * 0.55],
    [cap.r * 0.85, cap.to - 0.03], [cap.r * 0.95, cap.to - 0.015], [cap.r * 0.95, cap.to],
    [rS1 * 0.7, cap.to], [rS1 * 0.7, stemTop], [0.05, stemTop + 0.02], [0.03, stemTop + 0.05], [0, stemTop + 0.05],
  ], 16);
  // The boss's leaves: its widest band pressed into lobes, as the 1811 print's acanthus reads.
  {
    const P = turned.attributes.position;
    const y0 = collar.to + 0.01; const y1 = boss.to - 0.01;
    for (let i = 0; i < P.count; i += 1) {
      const y = P.getY(i);
      if (y <= y0 || y >= y1) continue;
      const x = P.getX(i); const z = P.getZ(i);
      const th = Math.atan2(z, x);
      const f = Math.sin(Math.PI * (y - y0) / (y1 - y0));
      const k = 1 - 0.14 * f * (0.5 - 0.5 * Math.cos((boss.leaves ?? 8) * th));
      P.setX(i, x * k); P.setZ(i, z * k);
    }
    turned.computeVertexNormals();
  }
  const h = lan.top - lan.foot;
  // A bar from (x0, y0, z0) to (x1, y1, z1), `t` thick.
  const rod = (a, b, t) => {
    const d = new THREE.Vector3(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
    const g = new THREE.BoxGeometry(t, d.length(), t);
    g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.clone().normalize()));
    g.translate((a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2);
    return g;
  };
  // A round iron bar bent along a curve through `pts` (start, bend, end), `r` its radius.
  const bent = (pts, r, seg = 10) => new THREE.TubeGeometry(
    new THREE.QuadraticBezierCurve3(...pts.map(([x, y, z]) => new THREE.Vector3(x, y, z))), seg, r, 4, false);
  const corners = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
  const faces = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  // The upper glass: from the waist band up to the neck under the cap. T-3231: the 1811
  // print sees the trees through it, as through the lower glass, so it is glazed, not tin.
  const upFrom = lan.top + rim.h; const upTo = roof.top;
  const upW = rim.w - 0.03;
  // The arms: four bars bent out of the stem's collar and up into the lantern's foot
  // corners, a cup under the lantern (T-3231: the 1811 print shows them curving up to
  // join the lantern, not standing up past it).
  const armFrom = stemTop - 0.05; const armR = 0.03;
  const footC = lan.w_foot / 2;
  const arms = corners.map(([sx, sz]) => bent([
    [sx * armR, armFrom, sz * armR],
    [sx * (footC + 0.03), armFrom - 0.01, sz * (footC + 0.03)],
    [sx * footC, lan.foot, sz * footC],
  ], 0.008));
  const near = {
    iron: merge([
      turned,
      // The ladder bar, across the post along the street, the lamplighter's rest, its ends knobbed.
      at(new THREE.BoxGeometry(bar.w, 0.022, 0.022), bar.at),
      ...[1, -1].map((s) => { const g = new THREE.SphereGeometry(0.018, 6, 4); g.translate(s * bar.w / 2, bar.at, 0); return g; }),
      // The stem's collar the arms spring from.
      at(new THREE.CylinderGeometry(0.035, 0.03, 0.03, 8), armFrom),
      ...arms,
      // The burner's pipe, standing in the lower glass.
      at(new THREE.CylinderGeometry(0.008, 0.008, h * 0.55, 5), lan.foot + h * 0.275),
      // The lantern's foot ring, its four corner bars and a middle bar on each face.
      at(square(lan.w_foot + 0.02, lan.w_foot + 0.02, 0.03), lan.foot),
      ...corners.map(([sx, sz]) => rod([sx * lan.w_foot / 2, lan.foot, sz * lan.w_foot / 2],
        [sx * lan.w_top / 2, lan.top, sz * lan.w_top / 2], 0.016)),
      ...faces.map(([sx, sz]) => rod([sx * lan.w_foot / 2, lan.foot, sz * lan.w_foot / 2],
        [sx * lan.w_top / 2, lan.top, sz * lan.w_top / 2], 0.009)),
      // The waist band where the lower glass meets the upper, projecting a little: a frame
      // of four bars, open, so the lantern is seen through from below.
      ...[0, 1, 2, 3].map((k) => {
        const g = new THREE.BoxGeometry(rim.w, rim.h, 0.024);
        g.translate(0, lan.top + rim.h / 2, rim.w / 2 - 0.012);
        g.rotateY((k * Math.PI) / 2);
        return g;
      }),
      // The upper glass's frame: a bar up each hip to the neck, and a light one up each face.
      ...corners.map(([sx, sz]) => rod([sx * upW / 2, upFrom, sz * upW / 2],
        [sx * roof.w_top / 2, upTo, sz * roof.w_top / 2], 0.014)),
      ...faces.map(([sx, sz]) => rod([sx * upW / 2, upFrom, sz * upW / 2],
        [sx * roof.w_top / 2, upTo, sz * roof.w_top / 2], 0.007)),
      // The neck ring under the cap.
      at(square(roof.w_top + 0.012, roof.w_top + 0.012, 0.018), upTo),
    ]),
    // The cap over the neck, its vent and the knob: tinned sheet, pale against the post.
    tin: merge([
      at(square(roof.w_top * 0.8, roof.w_top * 0.8, vent.h * 0.6), roof.top + vent.h * 0.3),
      at(square(0.02, vent.w, vent.h * 0.5), roof.top + vent.h * 0.85),
      at(new THREE.SphereGeometry(0.022, 8, 5), H - 0.022),
    ]),
    glass: merge([
      at(square(lan.w_top - 0.012, lan.w_foot - 0.004, h - 0.01, true), (lan.foot + lan.top) / 2),
      at(square(roof.w_top - 0.004, upW - 0.006, upTo - upFrom - 0.006, true), (upFrom + upTo) / 2),
    ]),
  };
  const far = {
    iron: merge([
      at(new THREE.CylinderGeometry(foot.r, foot.plinth_r, boss.to, 6), boss.to / 2),
      at(new THREE.CylinderGeometry(rS1, rS0, stemTop - boss.to, 5), (boss.to + stemTop) / 2),
      at(square(rim.w, rim.w, rim.h), lan.top + rim.h / 2),
    ]),
    tin: merge([
      at(square(roof.w_top * 0.8, roof.w_top * 0.8, vent.h), roof.top + vent.h / 2),
    ]),
    glass: merge([
      at(square(lan.w_top, lan.w_foot, h), (lan.foot + lan.top) / 2),
      at(square(roof.w_top, upW, upTo - upFrom), (upFrom + upTo) / 2),
    ]),
  };
  return { near, far };
}

/**
 * The globe lamp post (T-1934), in the post's own frame: Pullman's at the 18th Street walk's turn
 * into Calumet Avenue, as Taylor's no. 16554 shows it. A plain post on a plain base, painted
 * pale, a small bar a third of the way down, a slim neck into a fitter, a wide shallow globe and
 * a small cap. `m` is the data file's `model_by_class.globe_post`. Returns { paint, iron, opal }
 * for the near level and the far level.
 */
function globeLampGeometry(m) {
  const H = m.height_m ?? 4.9;
  const base = m.base_m ?? { r: 0.1, to: 0.5 };
  const [rS0, rS1] = m.shaft_r_m ?? [0.075, 0.06];
  const bar = m.ladder_bar_m ?? { at: 3.3, w: 0.3 };
  const neck = m.neck_m ?? { from: 3.95, to: 4.33, r: 0.04 };
  const globe = m.globe_m ?? { centre: 4.52, r: 0.29, ry: 0.19 };
  const cap = m.cap_m ?? { from: 4.7, r: 0.08 };
  const gTop = globe.centre + globe.ry;
  // The globe: a sphere pressed flat, its foot sitting in the fitter on the neck.
  const ball = (seg, rings) => {
    const g = new THREE.SphereGeometry(globe.r, seg, rings);
    g.scale(1, globe.ry / globe.r, 1);
    g.translate(0, globe.centre, 0);
    return g;
  };
  const post = (seg) => lathe([
    [0, 0], [base.r + 0.02, 0], [base.r + 0.02, 0.05], [base.r, 0.08], [base.r, base.to - 0.04],
    [rS0 + 0.015, base.to], [rS0, base.to + 0.03], [rS1, neck.from - 0.04], [rS1 + 0.01, neck.from - 0.02],
    [rS1 + 0.01, neck.from], [neck.r, neck.from + 0.03], [neck.r, neck.to], [0, neck.to],
  ], seg);
  const near = {
    paint: merge([post(16)]),
    iron: merge([
      // The bar, across the post along the street, its ends knobbed.
      at(new THREE.BoxGeometry(bar.w, 0.022, 0.022), bar.at),
      ...[1, -1].map((s) => { const g = new THREE.SphereGeometry(0.018, 6, 4); g.translate(s * bar.w / 2, bar.at, 0); return g; }),
      // The fitter: a cup on the neck that holds the globe's foot.
      at(new THREE.CylinderGeometry(globe.r * 0.42, neck.r + 0.01, globe.centre - globe.ry * 0.7 - neck.to, 12), (neck.to + globe.centre - globe.ry * 0.7) / 2),
      // The cap over the globe's crown, and its knob.
      lathe([[0, cap.from], [cap.r, cap.from], [cap.r * 0.9, cap.from + (H - cap.from) * 0.35],
        [cap.r * 0.4, H - 0.06], [0.02, H - 0.05], [0, H - 0.05]], 12),
      at(new THREE.SphereGeometry(0.025, 8, 5), H - 0.025),
      // The ring under the cap where it closes on the globe's crown.
      at(new THREE.CylinderGeometry(cap.r * 0.95, cap.r * 0.95, 0.02, 12), Math.max(cap.from, gTop - 0.03)),
    ]),
    opal: merge([ball(20, 10)]),
  };
  const far = {
    paint: merge([
      at(new THREE.CylinderGeometry(rS1, base.r, neck.to, 6), neck.to / 2),
    ]),
    iron: merge([
      at(new THREE.CylinderGeometry(cap.r * 0.4, cap.r, H - cap.from, 6), (H + cap.from) / 2),
    ]),
    opal: merge([ball(8, 5)]),
  };
  return { near, far };
}

function footingGeometry(m) {
  const f = m.footing_m ?? { w: 0.8, h: 0.02 };
  // A stone pad level with the walk, not a pedestal (T-3231: Taylor 2135's post stands on
  // one at the curb corner); sunk 0.1 m so it sits on a parkway that falls toward the curb.
  const g = new THREE.BoxGeometry(f.w, f.h + 0.1, f.w);
  g.translate(0, (f.h - 0.1) / 2, 0);
  const near = merge([g]);
  return { near, far: near.clone() };
}

/**
 * The post hydrant, in its own frame: y up from the ground, local x along the street (its
 * two nozzles point along it). `m` is the data file's `model_m`. Returns { near, far }.
 */
function hydrantGeometry(m) {
  const H = m.height_m ?? 0.85;
  const r = (m.barrel_d_m ?? 0.2) / 2;
  const foot = (m.foot_d_m ?? 0.34) / 2;
  const bandY = m.band_at_m ?? 0.62;
  const nozY = m.nozzles_at_m ?? 0.5;
  const domeY = bandY + 0.05;
  const near = merge([
    // The flared foot and the barrel, one turned profile up to the band.
    lathe([[0, 0], [foot, 0], [foot, 0.04], [foot * 0.8, 0.07], [r * 1.15, 0.13], [r, 0.18],
      [r, bandY - 0.03], [r * 1.22, bandY - 0.02], [r * 1.22, bandY + 0.03], [r * 1.05, domeY], [0, domeY]], 14),
    // The domed bonnet and the operating nut on its top.
    at(new THREE.SphereGeometry(r * 1.02, 14, 6, 0, Math.PI * 2, 0, Math.PI / 2), domeY),
    at(new THREE.CylinderGeometry(0.028, 0.032, H - domeY - r * 1.02 + 0.01, 5), (H + domeY + r * 1.02) / 2 - 0.005),
    // The two side nozzles and their caps, along the street.
    ...[1, -1].map((s) => {
      const g = merge([
        at(new THREE.CylinderGeometry(0.045, 0.05, 0.08, 10), 0),
        at(new THREE.CylinderGeometry(0.052, 0.052, 0.03, 6), 0.05),
      ]);
      g.rotateZ(-s * Math.PI / 2);
      g.translate(s * (r + 0.035), nozY, 0);
      return g;
    }),
  ]);
  const far = merge([
    at(new THREE.CylinderGeometry(r, foot * 0.9, domeY, 6), domeY / 2),
    at(new THREE.ConeGeometry(r, H - domeY, 6), (H + domeY) / 2),
  ]);
  return { near, far };
}

/**
 * A wooden pole (T-3202), in its own frame: y up from the ground, local x along its line, so a
 * crossarm lies along local z. `m` is one class of the data file's `model_m`. Returns
 * { near: { wood, glass }, far: { wood, glass: null } }; glass is null on a pole with no arm.
 */
function poleGeometry(m) {
  const H = m.height_m ?? 9.5;
  const rb = (m.butt_d_m ?? 0.28) / 2;
  const rt = (m.top_d_m ?? 0.18) / 2;
  const arms = m.arms ?? 0;
  const armY = H - (m.arm_below_top_m ?? 0.4);
  const armL = m.arm_len_m ?? 1.8;
  const pins = pinOffsets(m);
  const wood = [at(new THREE.CylinderGeometry(rt, rb, H, 8), H / 2)];
  const glass = [];
  for (let k = 0; k < arms; k += 1) {
    const y = armY - k * 0.6;
    wood.push(at(new THREE.BoxGeometry(0.09, 0.11, armL), y));
    for (const z of pins) {
      const pin = at(new THREE.CylinderGeometry(0.014, 0.018, 0.12, 4), y + 0.11);
      pin.translate(0, 0, z);
      wood.push(pin);
      const ins = at(new THREE.CylinderGeometry(0.03, 0.045, 0.09, 6), y + 0.2);
      ins.translate(0, 0, z);
      glass.push(ins);
    }
  }
  const farWood = [at(new THREE.CylinderGeometry(rt, rb, H, 4), H / 2)];
  if (arms) farWood.push(at(new THREE.BoxGeometry(0.1, 0.12, armL), armY));
  return {
    near: { wood: merge(wood), glass: glass.length ? merge(glass) : null },
    far: { wood: merge(farWood), glass: null },
  };
}

/** Where a crossarm's pins stand along it (local z), the middle left clear for the climber. */
function pinOffsets(m) {
  const n = m.pins ?? 0;
  const L = m.arm_len_m ?? 1.8;
  if (!n) return [];
  const half = Math.ceil(n / 2);
  const out = [];
  for (let i = 0; i < half; i += 1) {
    const z = 0.25 + (L / 2 - 0.35) * (half === 1 ? 0 : i / (half - 1)) + 0.05;
    out.push(z, -z);
  }
  return out.slice(0, n).sort((a, b) => a - b);
}

/** A sagging wire from a to b (THREE.Vector3s), as `seg` straight pieces pushed onto `pos`. */
function sagWire(pos, a, b, sag, seg = 8) {
  let px = a.x; let py = a.y; let pz = a.z;
  for (let i = 1; i <= seg; i += 1) {
    const f = i / seg;
    const x = a.x + (b.x - a.x) * f; const z = a.z + (b.z - a.z) * f;
    const y = a.y + (b.y - a.y) * f - 4 * sag * f * (1 - f);
    pos.push(px, py, pz, x, y, z);
    px = x; py = y; pz = z;
  }
}

/* -------------------------------------------------------------------------- */
/* the card                                                                    */
/* -------------------------------------------------------------------------- */

function citationsOf(doc, ids) {
  return [...new Set(ids)].map((id) => ({ source_id: id, ...(doc.sources?.[id] ?? {}) }));
}

const titleOf = (doc, id) => {
  const c = doc.sources?.[id]?.citation ?? id;
  return c.length > 90 ? `${c.slice(0, 88).trimEnd()}…` : c;
};

const CORNER_WORDS = { NE: 'north-east', NW: 'north-west', SE: 'south-east', SW: 'south-west' };

function itemCard(it, doc) {
  const kind = doc.kinds?.[it.kind] ?? {};
  const place = doc.placement?.[it.kind] ?? {};
  const attested = it.grade === 'attested';
  const where = it.where ?? (it.place === 'corner'
    ? `at the ${CORNER_WORDS[it.corner] ?? it.corner} corner of ${(it.streets ?? []).map((s) => doc.street_names?.[s] ?? s).join(' and ')}`
    : 'on the parkway, mid-block');
  const what = kind.what_by_class?.[it.class] ?? kind.what ?? 'A street lamp';
  const ruleNote = kind.rule_note_by_class?.[it.class] ?? kind.rule_note ?? '';
  const name = kind.name_by_class?.[it.class] ?? kind.name ?? 'street lamp';
  const form = kind.form_by_class?.[it.class] ?? kind.form ?? '';
  const formNote = kind.form_note_by_class?.[it.class] ?? kind.form_note ?? '';
  const formSources = kind.form_sources_by_class?.[it.class] ?? kind.form_sources ?? [];
  const pictures = (it.sources ?? []).map((id) => titleOf(doc, id));
  return {
    id: it.id,
    sidecar: {
      name: `A ${name}`,
      phase: null,
      change_note: attested
        ? `${what} ${where}, where a picture shows one: ${pictures.join('; ')}. ${it.note ?? ''}`.trim()
        : `${what} ${where}. ${ruleNote}; this one's place is ${it.grade === 'inferred' ? 'inferred' : 'our reconstruction'}.`,
      placement: {
        symbolic_location: it.face ?? (it.faces ?? []).join(' / '),
        position_confidence: it.grade,
        position_sources: it.sources ?? [],
        position_note: attested ? (it.note ?? '') : (place.note_by_class?.[it.class] ?? place.note ?? ''),
      },
      attributes: {
        kind: {
          value: name, confidence: kind.form_grade ?? 'inferred',
          sources: formSources, note: `${form} ${formNote}`.trim(),
        },
        position: {
          value: where, confidence: it.grade, sources: it.sources ?? [],
          note: attested ? (it.note ?? '') : `${place.note_by_class?.[it.class] ?? place.note ?? ''} ${it.liberty ?? ''}`.trim(),
        },
      },
      citations: citationsOf(doc, [...(it.sources ?? []), ...formSources]),
      research_doc: 'docs/RESEARCH/prairie_1904_street_furniture.md',
      research_note: `Item ${it.id} of data/street_furniture/1904.json (${kind.ticket ?? 'T-3199'}). ${it.liberty ?? ''}`.trim(),
    },
  };
}

/* -------------------------------------------------------------------------- */
/* the layer                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * @param {object} o dataBase (data/ root, or null when the scene does not list the
 *   layer) · sceneId · terrain · confidence · problems · detail · levelAt (the street
 *   grid's drop below the field at a point: the parkway falls toward the curb)
 */
export async function createStreetFurniture({
  dataBase, sceneId, terrain, confidence = null, problems = [], detail = 'full', levelAt = null,
} = {}) {
  const group = new THREE.Group();
  group.name = 'street-furniture';
  const stats = { items: 0, lamps: 0, hydrants: 0, near: 0, far: 0, hydrantsDrawn: 0, triangles: 0, drawCalls: 0, detail };
  const out = {
    group, stats, records: [],
    pickAt: () => null, update() {}, setDetail() {}, cardFor: () => null, dispose() {},
  };
  if (!dataBase || !terrain) return out;
  let doc;
  try {
    doc = await getJSON(new URL(`street_furniture/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`street furniture: ${err.message} — no street furniture is drawn`);
    return out;
  }
  const items = (doc.items ?? []).filter((it) => KINDS.includes(it.kind));
  out.records = items;
  stats.items = (doc.items ?? []).length;
  stats.lamps = items.filter((it) => it.kind === 'gas_lamp').length;
  stats.hydrants = items.filter((it) => it.kind === 'fire_hydrant').length;
  stats.poles = items.filter((it) => it.kind === 'utility_pole').length;
  if (!items.length) return out;

  /* ---- the parts, each one instanced geometry per level ------------------ */
  const model = doc.kinds?.gas_lamp?.model_m ?? {};
  const lamp = lampGeometry(model);
  const footing = footingGeometry(model);
  const footH = model.footing_m?.h ?? 0.02;
  const hydrantModel = doc.kinds?.fire_hydrant?.model_m ?? {};
  const hydrant = hydrantGeometry(hydrantModel);
  // A lamp whose class has a model of its own (T-1934: the globe post) is drawn with it;
  // every other lamp is the one post.
  const lampModels = doc.kinds?.gas_lamp?.model_by_class ?? {};
  const globes = Object.fromEntries(Object.entries(lampModels).map(([c, m]) => [c, globeLampGeometry(m)]));
  const isLamp = (it) => it.kind === 'gas_lamp';
  const isPost = (it) => isLamp(it) && !globes[it.class];
  const isHydrant = (it) => it.kind === 'fire_hydrant';
  const isPole = (it) => it.kind === 'utility_pole';
  const poleModels = doc.kinds?.utility_pole?.model_m ?? {};
  // Classes built alike share one geometry, so they share their draws.
  const poleKey = (c) => JSON.stringify(poleModels[c]);
  const poles = {};
  for (const c of POLE_CLASSES.filter((x) => poleModels[x])) {
    const k = poleKey(c);
    if (!poles[k]) poles[k] = { classes: [], geo: poleGeometry(poleModels[c]) };
    poles[k].classes.push(c);
  }
  const mats = {
    iron: new THREE.MeshStandardMaterial({ color: 0x343a34, roughness: 0.6, metalness: 0.3 }),
    tin: new THREE.MeshStandardMaterial({ color: 0xd0d4ce, roughness: 0.45, metalness: 0.05 }),
    // Clear panes: the 1811 print sees the street through them, so they read light only where
    // they catch the sky, never as a lit box.
    glass: new THREE.MeshStandardMaterial({ color: 0xdfe6e6, roughness: 0.06, metalness: 0.2, transparent: true, opacity: 0.38, depthWrite: false, side: THREE.DoubleSide }),
    stone: new THREE.MeshStandardMaterial({ color: 0xbab3a3, roughness: 0.92, metalness: 0 }),
    // The Detroit view prints the hydrant lighter than the lamp posts: a mid-grey paint.
    hydrant: new THREE.MeshStandardMaterial({ color: 0x6f6e66, roughness: 0.6, metalness: 0.25 }),
    // Creosoted cedar, weathered; the insulators are the usual green glass.
    wood: new THREE.MeshStandardMaterial({ color: 0x5a4a3a, roughness: 0.95, metalness: 0 }),
    insulator: new THREE.MeshStandardMaterial({ color: 0x7fa596, roughness: 0.2, metalness: 0.05 }),
    // The globe post's paint: Taylor 16554 prints it lighter than the sunlit stone behind it.
    paint: new THREE.MeshStandardMaterial({ color: 0xd2cec2, roughness: 0.55, metalness: 0.05 }),
    // Its globe: lit above and dark beneath in the print, so a milky glass, not a clear one.
    opal: new THREE.MeshStandardMaterial({ color: 0xeeeeea, roughness: 0.3, metalness: 0, transparent: true, opacity: 0.92 }),
  };
  for (const [k, m] of Object.entries(mats)) { m.name = `street-furniture-${k}`; confidence?.patch(m); }
  const parts = [
    { name: 'lamp-iron', geo: lamp, key: 'iron', mat: mats.iron, lift: (it) => (it.footing ? footH : 0), on: isPost, body: true },
    { name: 'lamp-tin', geo: lamp, key: 'tin', mat: mats.tin, lift: (it) => (it.footing ? footH : 0), on: isPost },
    { name: 'lamp-glass', geo: lamp, key: 'glass', mat: mats.glass, lift: (it) => (it.footing ? footH : 0), on: isPost },
    ...Object.entries(globes).flatMap(([c, geo]) => [
      { name: `lamp-${c}-paint`, geo, key: 'paint', mat: mats.paint, lift: (it) => (it.footing ? footH : 0), on: (it) => isLamp(it) && it.class === c, body: true },
      { name: `lamp-${c}-iron`, geo, key: 'iron', mat: mats.iron, lift: (it) => (it.footing ? footH : 0), on: (it) => isLamp(it) && it.class === c },
      { name: `lamp-${c}-opal`, geo, key: 'opal', mat: mats.opal, lift: (it) => (it.footing ? footH : 0), on: (it) => isLamp(it) && it.class === c },
    ]),
    { name: 'lamp-footing', geo: footing, key: null, mat: mats.stone, lift: () => 0, on: (it) => !!it.footing },
    { name: 'hydrant', geo: hydrant, key: null, mat: mats.hydrant, lift: () => 0, on: isHydrant, far: HYDRANT_FAR_M },
    ...Object.values(poles).flatMap(({ classes, geo }) => [
      { name: `pole-${classes.join('-')}-wood`, geo, key: 'wood', mat: mats.wood, lift: () => 0, on: (it) => isPole(it) && classes.includes(it.class) },
      { name: `pole-${classes.join('-')}-glass`, geo, key: 'glass', mat: mats.insulator, lift: () => 0, on: (it) => isPole(it) && classes.includes(it.class) },
    ]),
  ];

  /* ---- where each lamp stands, once ------------------------------------- */
  const up = new THREE.Vector3(0, 1, 0);
  const placed = items.map((it) => {
    const y = terrain.surfaceHeight(it.e, it.n) + (levelAt?.(it.e, it.n) ?? 0) + PARKWAY_LIFT_M;
    // heading_deg is a compass bearing; the post's local x is turned onto it.
    const q = new THREE.Quaternion().setFromAxisAngle(up, (90 - (it.heading_deg ?? 0)) * Math.PI / 180);
    return { it, y, q, x: it.e, z: -it.n, conf: CONF[it.grade] ?? 1 };
  });

  /* ---- one InstancedMesh per part per level ----------------------------- */
  const meshes = [];
  for (const part of parts) {
    for (const level of ['near', 'far']) {
      const src = part.key ? part.geo[level][part.key] : part.geo[level];
      if (!src) continue;
      const geo = src.clone();
      const max = placed.filter((p) => part.on(p.it)).length;
      if (!max) continue;
      geo.setAttribute('_confidence', new THREE.InstancedBufferAttribute(new Float32Array(max), 1));
      const mesh = new THREE.InstancedMesh(geo, part.mat, max);
      mesh.name = `street-furniture-${part.name}-${level}`;
      mesh.count = 0;
      mesh.castShadow = false;
      mesh.receiveShadow = true;
      mesh.userData = { part, level, max };
      group.add(mesh);
      meshes.push(mesh);
    }
  }
  for (const g of [lamp.near.iron, lamp.near.tin, lamp.near.glass, lamp.far.iron, lamp.far.tin, lamp.far.glass, footing.near, footing.far,
    hydrant.near, hydrant.far]) g.dispose();
  for (const g of Object.values(globes)) for (const l of [g.near, g.far]) for (const x of Object.values(l)) x.dispose();
  for (const { geo: g } of Object.values(poles)) for (const l of [g.near, g.far]) for (const x of [l.wood, l.glass]) x?.dispose();

  /* ---- the wires (T-3202): one static set of line segments, off on light -- */
  const byId = new Map(placed.map((p) => [p.it.id, p]));
  const pinWorld = (p, z, y) => {
    const v = new THREE.Vector3(0, y, z).applyQuaternion(p.q);
    return new THREE.Vector3(p.x + v.x, p.y + v.y, p.z + v.z);
  };
  const wirePos = [];
  for (const w of doc.wires ?? []) {
    if (w.kind === 'line') {
      const a = byId.get(w.from); const b = byId.get(w.to);
      if (!a || !b) continue;
      const ma = poleModels[a.it.class] ?? {}; const mb = poleModels[b.it.class] ?? {};
      const za = pinOffsets(ma); const zb = pinOffsets(mb);
      const n = Math.min(za.length, zb.length);
      const ya = (ma.height_m ?? 9.5) - (ma.arm_below_top_m ?? 0.4) + 0.24;
      const yb = (mb.height_m ?? 9.5) - (mb.arm_below_top_m ?? 0.4) + 0.24;
      // Match each wire to the pin on the same side of both arms, seen along the span.
      const pa = za.map((z) => pinWorld(a, z, ya)); const pb = zb.map((z) => pinWorld(b, z, yb));
      const dir = new THREE.Vector3(b.x - a.x, 0, b.z - a.z).normalize();
      const side = (v, p) => (v.x - p.x) * -dir.z + (v.z - p.z) * dir.x;
      pa.sort((u, v) => side(u, a) - side(v, a)); pb.sort((u, v) => side(u, b) - side(v, b));
      const span = Math.hypot(b.x - a.x, b.z - a.z);
      for (let i = 0; i < n; i += 1) {
        const j = Math.round((i * (pa.length - 1)) / Math.max(1, n - 1));
        const k = Math.round((i * (pb.length - 1)) / Math.max(1, n - 1));
        sagWire(wirePos, pa[j], pb[k], (doc.wire_model?.sag_frac ?? 0.012) * span);
      }
    } else if (w.kind === 'trolley_span') {
      const a = byId.get(w.from); const b = byId.get(w.to);
      if (!a || !b) continue;
      const h = poleModels.trolley?.span_at_m ?? 6.6;
      sagWire(wirePos, new THREE.Vector3(a.x, a.y + h, a.z), new THREE.Vector3(b.x, b.y + h, b.z),
        doc.wire_model?.trolley?.span_sag_m ?? 0.35, 10);
    } else if (w.kind === 'trolley_contact') {
      const t = doc.wire_model?.trolley ?? {};
      const hangs = (w.between_spans ?? []).map(([ia, ib]) => {
        const a = byId.get(ia); const b = byId.get(ib);
        if (!a || !b) return null;
        const mid = new THREE.Vector3((a.x + b.x) / 2, Math.min(a.y, b.y) + (t.contact_h_m ?? 5.6), (a.z + b.z) / 2);
        const across = new THREE.Vector3(b.x - a.x, 0, b.z - a.z).normalize();
        return { mid, across };
      });
      if (hangs.length !== 2 || hangs.includes(null)) continue;
      const g = (t.contact_gap_m ?? 3.0) / 2;
      for (const s of [-1, 1]) {
        const p0 = hangs[0].mid.clone().addScaledVector(hangs[0].across, s * g);
        const p1 = hangs[1].mid.clone().addScaledVector(hangs[1].across, s * g);
        sagWire(wirePos, p0, p1, 0.08, 4);
        // The hanger up to the span wire at each end.
        for (const p of [p0, p1]) wirePos.push(p.x, p.y, p.z, p.x, p.y + 0.6, p.z);
      }
    }
  }
  let wires = null;
  if (wirePos.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(wirePos, 3));
    g.computeBoundingSphere();
    mats.wire = new THREE.LineBasicMaterial({ color: 0x1e201d });
    mats.wire.name = 'street-furniture-wire';
    wires = new THREE.LineSegments(g, mats.wire);
    wires.name = 'street-furniture-wires';
    wires.castShadow = false; wires.receiveShadow = false;
    group.add(wires);
    stats.wireSegments = wirePos.length / 6;
  }

  /* ---- the deal: which lamps each level draws, from where the eye is ----- */
  let tier = RINGS[detail] ? detail : 'full';
  const last = new THREE.Vector3(Infinity, 0, 0);
  const m4 = new THREE.Matrix4(); const pos = new THREE.Vector3(); const one = new THREE.Vector3(1, 1, 1);
  const deal = (eye) => {
    const ring = RINGS[tier];
    let triangles = 0; let calls = 0; let nearN = 0; let farN = 0; let hydN = 0; let poleN = 0;
    for (const mesh of meshes) {
      const { part, level } = mesh.userData;
      const conf = mesh.geometry.getAttribute('_confidence');
      let k = 0;
      for (const p of placed) {
        if (!part.on(p.it)) continue;
        const d = Math.hypot(p.x - eye.x, p.z - eye.z);
        const farM = part.far ? Math.min(ring.far, part.far[tier] ?? ring.far) : ring.far;
        const lvl = d <= ring.near ? 'near' : (d <= farM ? 'far' : null);
        if (lvl !== level) continue;
        pos.set(p.x, p.y + part.lift(p.it), p.z);
        mesh.setMatrixAt(k, m4.compose(pos, p.q, one));
        conf.array[k] = p.conf;
        k += 1;
      }
      mesh.count = k;
      mesh.instanceMatrix.needsUpdate = true;
      conf.needsUpdate = true;
      mesh.visible = k > 0;
      mesh.castShadow = level === 'near' && ring.shadow;
      if (k) {
        mesh.computeBoundingSphere();
        calls += 1;
        triangles += k * (mesh.geometry.attributes.position.count / 3);
        if (part.body) { if (level === 'near') nearN += k; else farN += k; }
        if (part.name === 'hydrant') hydN += k;
        if (part.name.startsWith('pole-') && part.name.endsWith('-wood')) poleN += k;
      }
    }
    if (wires) {
      // The wires are a thread a pixel wide: they cost a draw, so the phone tier leaves them off.
      wires.visible = tier !== 'light';
      if (wires.visible) { calls += 1; }
    }
    stats.near = nearN; stats.far = farN; stats.hydrantsDrawn = hydN; stats.polesDrawn = poleN;
    stats.wiresShown = !!wires?.visible; stats.triangles = triangles; stats.drawCalls = calls; stats.detail = tier;
    last.copy(eye);
  };

  out.update = (_dt, camera = null) => {
    if (!camera) return;
    const eye = camera.position;
    if (Math.hypot(eye.x - last.x, eye.z - last.z) >= REDEAL_M) deal(eye);
  };
  out.setDetail = (d) => {
    if (!RINGS[d] || d === tier) return;
    tier = d;
    if (Number.isFinite(last.x)) deal(last.clone());
  };
  /** Deal now, from this eye (a still frame for a reading or a shot). */
  out.settle = (camera) => { if (camera) deal(camera.position.clone()); };

  /* ---- picks: a post under the crosshair -------------------------------- */
  const ray = new THREE.Raycaster();
  const height = (model.finial_top_m ?? 3.1);
  const hydrantH = hydrantModel.height_m ?? 0.85;
  const poleH = (c) => poleModels[c]?.height_m ?? 9.5;
  out.pickAt = (ndc, camera) => {
    if (!camera || !group.visible) return null;
    ray.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    const o = ray.ray.origin; const d = ray.ray.direction;
    const a = d.x * d.x + d.z * d.z;
    if (a < 1e-9) return null;
    let best = null;
    for (const p of placed) {
      const lift = p.it.footing ? footH : 0;
      const hyd = isHydrant(p.it);
      const isP = isPole(p.it);
      const dx = o.x - p.x; const dz = o.z - p.z;
      const tt = -(dx * d.x + dz * d.z) / a;
      if (!(tt > 0 && tt < 200)) continue;
      const px = dx + d.x * tt; const pz = dz + d.z * tt;
      const yy = o.y + d.y * tt;
      // The column is thin; the pick takes a lantern's width so a post can be hit.
      const r = isP ? 0.25 : (hyd ? 0.24 : (yy > p.y + lift + 2.3 ? 0.26 : 0.16));
      const top = isP ? poleH(p.it.class) : (hyd ? hydrantH : (lampModels[p.it.class]?.height_m ?? height));
      if (px * px + pz * pz < r * r && yy > p.y - 0.1 && yy < p.y + lift + top
        && (!best || tt < best.distance)) {
        best = { p, distance: tt, point: new THREE.Vector3(o.x + d.x * tt, yy, o.z + d.z * tt) };
      }
    }
    if (!best) return null;
    const record = itemCard(best.p.it, doc);
    return { id: record.id, record, point: best.point, distance: best.distance };
  };
  out.cardFor = (id) => {
    const it = items.find((x) => x.id === id);
    return it ? itemCard(it, doc) : null;
  };
  out.dispose = () => {
    for (const m of meshes) m.geometry.dispose();
    wires?.geometry.dispose();
    for (const m of Object.values(mats)) m.dispose();
  };
  return out;
}
